class RunSnapshot(WireModel):
    model_config = ConfigDict(
        extra="allow", populate_by_name=True, strict=True, frozen=True, allow_inf_nan=False
    )
    pause: RunPause | None = None
    limits_revision: Annotated[int, Field(ge=0)] | None = None
    pause_expires_at_ms: Annotated[int, Field(ge=0)] | None = None
    api_version: (
        Annotated[str, Field(pattern="^(0|[1-9][0-9]*)\\.(0|[1-9][0-9]*)\\.(0|[1-9][0-9]*)$")]
        | None
    ) = None
    variant: SwarmsVariantVersion | None = None
    metadata: dict[str, JsonValue]
    method: JsonValue | None = None
    run_id: RunId
    labels: dict[str, str] | None
    labels_revision: int
    objectives: list[RunObjective] | None
    objectives_read: (
        Annotated[RunSnapshotObjectivesRead, BeforeValidator(enum_value(RunSnapshotObjectivesRead))]
        | None
    ) = None
    guidance_coverage: list[JsonValue] | None
    state: str
    model: str
    provider: str
    result_available: bool
    execution_closed: bool
    accounting_final: bool
    cleanup_complete: bool
    control: ControlRef | None = None
    problems: list[RunProblem] | None
    problems_observed: bool
    charge: RunCharge | None = None
    failure: JsonValue | None = None
    created_at: str
    started_at: str | None
    closed_at: str | None
    profile: RunProfilePin | None = None
    selection: RunSelection | None = None
    routing: RoutingReadback | None = None

    @property
    def known_state(self) -> RunState | None:
        try:
            return RunState(self.state)
        except ValueError:
            return None

    @property
    def finished(self) -> bool:
        return self.execution_closed and self.accounting_final and self.cleanup_complete

    def reached(self, milestone: CompletionMilestone) -> bool:
        milestone = CompletionMilestone(milestone)
        if milestone is CompletionMilestone.PAUSED:
            return self.state == "paused"
        if milestone is CompletionMilestone.FINISHED:
            return self.finished
        if milestone is CompletionMilestone.EXECUTION_CLOSED:
            return self.execution_closed
        return self.result_available


